// src/components/BottomNav.jsx
import React from "react";
import { Link } from "react-router-dom";

export default function BottomNav() {
  return (
    <footer
      className="fixed bottom-0 inset-x-0 z-50 bg-gray-900/95 backdrop-blur border-t border-gray-700 text-gray-300"
      role="contentinfo"
      aria-label="Site footer"
    >
      <div className="mx-auto max-w-6xl px-3 md:px-4">
        <div className="flex flex-wrap items-center justify-between gap-2 md:gap-4 py-2 text-[11px] md:text-xs">
          {/* Left: Copyright */}
          <div className="shrink-0">
            © 2025 TutorSimula. All rights reserved.
          </div>

          {/* Center: Social icons */}
          <div className="flex items-center gap-3 md:gap-4">
            {/* LinkedIn */}
            <a
              href="https://www.linkedin.com/company/tutorsimula"
              target="_blank"
              rel="noopener noreferrer"
              aria-label="TutorSimula on LinkedIn"
              className="hover:text-white"
              title="LinkedIn"
            >
              <svg viewBox="0 0 24 24" className="h-4 w-4 md:h-5 md:w-5" fill="currentColor" aria-hidden="true">
                <path d="M4.98 3.5A2.5 2.5 0 1 1 5 8.5a2.5 2.5 0 0 1-.02-5zM4 9h2.99v12H4zM9 9h2.86v1.64h.04c.4-.76 1.38-1.56 2.84-1.56C18.07 9.08 19 11 19 13.9V21h-3v-6.08c0-1.45-.03-3.31-2.02-3.31-2.03 0-2.34 1.58-2.34 3.21V21H9z"/>
              </svg>
            </a>

            {/* X (Twitter) */}
            <a
              href="https://x.com/tutorsimula"
              target="_blank"
              rel="noopener noreferrer"
              aria-label="TutorSimula on X (Twitter)"
              className="hover:text-white"
              title="X"
            >
              <svg viewBox="0 0 24 24" className="h-4 w-4 md:h-5 md:w-5" fill="currentColor" aria-hidden="true">
                <path d="M18.244 2H21l-6.74 7.71L22 22h-6.9l-5.4-6.74L3.62 22H1l7.23-8.28L2 2h6.9l4.86 6.11L18.244 2zm-2.42 18h1.85L8.24 4H6.3l9.524 16z"/>
              </svg>
            </a>

            {/* YouTube */}
            <a
              href="https://www.youtube.com/@TutorSimula"
              target="_blank"
              rel="noopener noreferrer"
              aria-label="TutorSimula on YouTube"
              className="hover:text-white"
              title="YouTube"
            >
              <svg viewBox="0 0 24 24" className="h-4 w-4 md:h-5 md:w-5" fill="currentColor" aria-hidden="true">
                <path d="M23.5 6.2a3 3 0 0 0-2.1-2.1C19.6 3.5 12 3.5 12 3.5s-7.6 0-9.4.6A3 3 0 0 0 .5 6.2C0 8 0 12 0 12s0 4 .5 5.8a3 3 0 0 0 2.1 2.1c1.8.6 9.4.6 9.4.6s7.6 0 9.4-.6a3 3 0 0 0 2.1-2.1C24 16 24 12 24 12s0-4-.5-5.8zM9.75 15.5v-7l6 3.5-6 3.5z"/>
              </svg>
            </a>

            {/* Facebook */}
            <a
              href="https://www.facebook.com/tutorsimula"
              target="_blank"
              rel="noopener noreferrer"
              aria-label="TutorSimula on Facebook"
              className="hover:text-white"
              title="Facebook"
            >
              <svg viewBox="0 0 24 24" className="h-4 w-4 md:h-5 md:w-5" fill="currentColor" aria-hidden="true">
                <path d="M22.676 0H1.324C.593 0 0 .593 0 1.324v21.352C0 23.407.593 24 1.324 24h11.495v-9.294H9.691v-3.622h3.128V8.413c0-3.1 1.893-4.788 4.659-4.788 1.325 0 2.463.099 2.795.143v3.24l-1.918.001c-1.504 0-1.797.715-1.797 1.764v2.314h3.592l-.467 3.622h-3.125V24h6.127C23.407 24 24 23.407 24 22.676V1.324C24 .593 23.407 0 22.676 0z"/>
              </svg>
            </a>

            {/* Instagram */}
            <a
              href="https://www.instagram.com/tutorsimula"
              target="_blank"
              rel="noopener noreferrer"
              aria-label="TutorSimula on Instagram"
              className="hover:text-white"
              title="Instagram"
            >
              <svg viewBox="0 0 24 24" className="h-4 w-4 md:h-5 md:w-5" fill="currentColor" aria-hidden="true">
                <path d="M7.5 2h9A5.5 5.5 0 0 1 22 7.5v9A5.5 5.5 0 0 1 16.5 22h-9A5.5 5.5 0 0 1 2 16.5v-9A5.5 5.5 0 0 1 7.5 2zm0-2A7.5 7.5 0 0 0 0 7.5v9A7.5 7.5 0 0 0 7.5 24h9A7.5 7.5 0 0 0 24 16.5v-9A7.5 7.5 0 0 0 16.5 0h-9zM12 7.5A4.5 4.5 0 1 0 12 16.5 4.5 4.5 0 0 0 12 7.5zm7-2a1.5 1.5 0 1 0 0 3 1.5 1.5 0 0 0 0-3z"/>
              </svg>
            </a>
          </div>

          {/* Right: Legal links */}
          <div className="flex items-center gap-3 md:gap-4">
            <Link to="/terms" className="hover:text-white underline-offset-2 hover:underline">
              Terms &amp; Conditions
            </Link>
            <span className="opacity-40">•</span>
            <Link to="/privacy" className="hover:text-white underline-offset-2 hover:underline">
              Privacy Policy
            </Link>
            <span className="opacity-40">•</span>
            <Link to="/cookies" className="hover:text-white underline-offset-2 hover:underline">
              Cookie Policy
            </Link>
          </div>
        </div>
      </div>

      {/* iOS safe-area */}
      <div style={{ paddingBottom: "env(safe-area-inset-bottom)" }} />
    </footer>
  );
}
